<?php

/* @autogenerated */
declare(strict_types=1);

namespace Tests\unit\Features\OAuth\UserInvitation;

use Civi\Lughauth\Features\OAuth\Authentication\Infrastructure\Driver\Html\Services\OidcCookieManager;
use Civi\Lughauth\Features\OAuth\Client\Domain\ClientData;
use Civi\Lughauth\Features\OAuth\Client\Domain\Gateway\ClientStoreGateway;
use Civi\Lughauth\Features\OAuth\Theme\Application\DecorateHtml;
use Civi\Lughauth\Features\OAuth\UserInvitation\Application\Usecase\Accept\InvitationAcceptParams;
use Civi\Lughauth\Features\OAuth\UserInvitation\Application\Usecase\Accept\InvitationAcceptResult;
use Civi\Lughauth\Features\OAuth\UserInvitation\Application\Usecase\Accept\InvitationAcceptUsecase;
use Civi\Lughauth\Features\OAuth\UserInvitation\Infrastructure\Driver\Html\InvitationAcceptHtml;
use Civi\Lughauth\Shared\Context;
use Nimbly\Capsule\Factory\ServerRequestFactory;
use Nimbly\Capsule\Response;
use PHPUnit\Framework\TestCase;
use Psr\Http\Message\RequestInterface;

final class InvitationAcceptHtmlUnitTest extends TestCase
{
    public function testRegisteredRedirectShowsLinkToClientOrigin(): void
    {
        $html = $this->acceptInvitation(true);

        self::assertStringContainsString('<a class="primary-button" href="https://app.example.com">Login now</a>', $html);
    }

    public function testUnregisteredRedirectDoesNotShowLoginLink(): void
    {
        $html = $this->acceptInvitation(false);

        self::assertStringContainsString('Account activated', $html);
        self::assertStringNotContainsString('Login now', $html);
        self::assertStringNotContainsString('attacker.example', $html);
    }

    private function acceptInvitation(bool $registered): string
    {
        $redirect = $registered
            ? 'https://app.example.com/login-redirect'
            : 'https://attacker.example/login-redirect';
        $usecase = $this->createMock(InvitationAcceptUsecase::class);
        $usecase->expects(self::once())->method('accept')
            ->with(self::callback(
                static fn (InvitationAcceptParams $params): bool =>
                $params->tenantName === 'main'
                && $params->clientId === 'lughauth-ui'
                && $params->redirectUri === $redirect
            ))
            ->willReturn(new InvitationAcceptResult('user@example.com', null));

        $clients = $this->createMock(ClientStoreGateway::class);
        $clients->expects(self::once())->method('publicClientData')
            ->with('lughauth-ui', 'main', $redirect, '')
            ->willReturn($registered ? new ClientData('lughauth-ui', ['authorization_code'], false) : null);

        $decorator = $this->createStub(DecorateHtml::class);
        $decorator->method('getFullPage')->willReturnCallback(
            static fn (RequestInterface $request, string $title, string $innerContent): string => $innerContent
        );
        $controller = new InvitationAcceptHtml(
            $usecase,
            $decorator,
            $this->createStub(OidcCookieManager::class),
            $this->createStub(Context::class),
            $clients,
        );
        $request = (new ServerRequestFactory())
            ->createServerRequest('POST', '/oauth/openid/main/invitation/accept')
            ->withParsedBody([
                'token' => 'valid-invitation',
                'password' => 'new-password',
                'client_id' => 'lughauth-ui',
                'redirect_uri' => $redirect,
            ]);

        $response = $controller->accept($request, new Response(200), ['tenant' => 'main']);
        self::assertSame(200, $response->getStatusCode());
        return (string) $response->getBody();
    }
}
